/**
 * @file    isr.hpp
 * @brief   The shared face between ISR stubs and the exception reporter.
 *
 * Stubs are generated by the compiler from the x86 interrupt attribute —
 * no macro arrays, no hand-written assembly. Each template instantiation
 * bakes its vector number into the call it makes, and the two signature
 * shapes (with and without a CPU-pushed error code) funnel into the one
 * reporter below with a uniform frame pointer.
 *
 * @author  Charliechen114514
 * @date    2026-10-02
 * @version 0.1
 * @since   0.1.0
 * @ingroup kernel_arch
 * @copyright Copyright (c) 2026
 */

#pragma once

namespace cinux::arch::isr {

/// The vector the CPU hands the kernel for a page fault.
inline constexpr unsigned long long kPageFaultVector = 14;

/// Page-fault error code, bit 0: the mapping exists; the fault is a
/// permission clash, not a missing page.
inline constexpr unsigned long long kFaultProtection = 1ULL << 0U;

/// Page-fault error code, bit 1: the access was a write.
inline constexpr unsigned long long kFaultWasWrite = 1ULL << 1U;

/// Page-fault error code, bit 2: the access came from ring 3.
inline constexpr unsigned long long kFaultFromUser = 1ULL << 2U;

/**
 * @brief         One chance to answer a page fault without dying.
 * @param[in]     address     CR2 as the handler read it.
 * @param[in]     error_code  The CPU-pushed fault code.
 * @return        true when the mapping was repaired and the faulting
 *                instruction may re-run; false to fall through to the
 *                dump (or an armed recovery).
 * @since         0.2.0
 * @ingroup       kernel_arch
 */
using PageFaultResolver = bool (*)(unsigned long long address, unsigned long long error_code);

struct [[gnu::packed]] InterruptFrame {
    unsigned long long rip;
    unsigned long long cs;
    unsigned long long rflags;
    unsigned long long rsp;
    unsigned long long ss;
};

/**
 * @brief         Report one fault: named vector plus the frame that caused it.
 * @param[in]     vector      CPU exception number, 0..31.
 * @param[in,out] frame       The frame the stub received; rip moves forward
 *                            when an armed recovery consumes this fault.
 * @param[in]     error_code  CPU-pushed code, 0 for no-code exceptions.
 * @return        None.
 * @note          An armed-and-matching fault is repaired and returned
 *                through iret; every other fault prints the dump and
 *                parks the machine.
 * @since         0.1.0
 * @ingroup       kernel_arch
 */
void ReportFault(unsigned long long vector, InterruptFrame& frame, unsigned long long error_code);

/**
 * @brief         Arm one fault as expected and resumable.
 * @param[in]     vector       The exception number to intercept.
 * @param[in]     skip_bytes   Instruction length to step rip past on resume.
 * @return        true when armed; false when a previous arm is pending.
 * @note          The resumable-fault probe, a miniature of the exception
 *                tables real kernels use for speculative access: when the
 *                armed vector fires, the reporter advances rip by
 *                skip_bytes and iret-returns instead of dumping. Any other
 *                fault, or one nobody armed, behaves as always.
 * @since         0.2.0
 * @ingroup       kernel_arch
 */
bool ArmRecoverableFault(unsigned long long vector, unsigned long long skip_bytes);

/**
 * @brief         Take the vector of the last recovered fault, if any.
 * @return        The recovered vector, or 256 — one past all real CPU
 *                vectors — when the arm never fired.
 * @note          Reading consumes the record; a second call without a new
 *                recovery answers 256, the no-fault sentinel.
 * @since         0.2.0
 * @ingroup       kernel_arch
 */
unsigned long long TakeRecoveredVector();

/**
 * @brief         Seat the one resolver every page fault is offered to.
 * @param[in]     resolver   The callback, or nullptr to uninstall.
 * @return        None.
 * @note          The memory theme's copy-on-write answer installs here;
 *                a resolver that declines (returns false) changes nothing,
 *                the fault falls through to the armed-recovery probe and
 *                then the dump. One seat on purpose: the kernel has one
 *                story about why a page fault may be survivable.
 * @since         0.2.0
 * @ingroup       kernel_arch
 */
void InstallPageFaultResolver(PageFaultResolver resolver);

/**
 * @brief         The shape of the reporter's second opinion on a dead fault.
 * @param[in]     address      The faulting virtual address, as CR2 held it.
 * @param[in]     error_code   The stub's error word.
 * @return        None.
 * @note          Called only after the resolver has declined and the fault
 *                is on its way to the dump; whatever this prints is
 *                evidence, never control flow.
 * @since         0.3.0
 * @ingroup       kernel_arch
 */
using PageFaultDiagnoser = void (*)(unsigned long long address, unsigned long long error_code);

/**
 * @brief         Seat the one diagnoser declined faults are shown to.
 * @param[in]     diagnoser   The callback, or nullptr to uninstall.
 * @return        None.
 * @note          A mirror of the resolver seat: arch owns the seat, the
 *                memory theme owns the knowledge, so the reporter never
 *                learns what a range register is. The diagnoser runs after
 *                the resolver declines and before the dump; a pending
 *                armed recovery still fires after it.
 * @since         0.3.0
 * @ingroup       kernel_arch
 */
void InstallPageFaultDiagnoser(PageFaultDiagnoser diagnoser);

/**
 * @brief         Arm all 32 CPU exception vectors with attribute stubs.
 * @return        None.
 * @note          Vectors 8, 10-14, 17, 21, 29 and 30 take the error-code
 *                signature; the rest take the bare one. Every stub here
 *                lands before lidt makes the table live.
 * @since         0.1.0
 * @ingroup       kernel_arch
 */
void InstallExceptionStubs();

}  // namespace cinux::arch::isr
